  void render_prefersTenantSpecificTemplateOverGlobal() {
    TenantRef tenant = () -> "T1";
    Template global = globalTemplate("CODE");
    Template tenantSpecific = tenantTemplate("CODE", tenant);
    TemplateVersion version = version("<p>Tenant</p>");

    when(templateGateway.list(any())).thenReturn(List.of(global, tenantSpecific));
    when(versionGateway.list(any())).thenReturn(List.of(version));
    RenderedTemplate rendered = mock(RenderedTemplate.class);
    when(renderGateway.render(any())).thenReturn(rendered);

    Optional<RenderedTemplate> result = usecase.render(input("CODE", tenant, Map.of()));

    assertTrue(result.isPresent());
  }

