  @Test
  @DisplayName("render selects the version with the highest version number when multiple exist")
  void render_selectsLatestVersionWhenMultipleExist() {
    Template template = globalTemplate("CODE");
    TemplateVersion older = version("<p>Old</p>");
    when(older.getVersion()).thenReturn(Optional.of(1));
    TemplateVersion newer = version("<p>New</p>");
    when(newer.getVersion()).thenReturn(Optional.of(3));
    TemplateVersion middle = version("<p>Mid</p>");
    when(middle.getVersion()).thenReturn(Optional.of(2));

    when(templateGateway.list(any())).thenReturn(List.of(template));
    when(versionGateway.list(any())).thenReturn(List.of(older, middle, newer));
    RenderedTemplate rendered = mock(RenderedTemplate.class);
    when(renderGateway.render(any())).thenReturn(rendered);

    usecase.render(input("CODE", null, Map.of()));

    // Verify that the render request uses the html content of the newest version
    verify(renderGateway).render(argThat(req -> "<p>New</p>".equals(req.getHtmlContent())));
  }

  @Test
  @DisplayName("render merges tenant variables with call-site overrides; overrides win")
  void render_mergesVariablesWithTenantDefaults() {
    TenantRef tenant = () -> "T1";
    Template template = tenantTemplate("CODE", tenant);
    TemplateVersion version = version("<p>Hello</p>");

    TemplateVariable dbVar = mock(TemplateVariable.class);
    when(dbVar.isEnabled()).thenReturn(true);
    when(dbVar.getCode()).thenReturn("greeting");
    when(dbVar.getValue()).thenReturn(Optional.of("Hi"));

    TemplateVariable overriddenVar = mock(TemplateVariable.class);
    when(overriddenVar.isEnabled()).thenReturn(true);
    when(overriddenVar.getCode()).thenReturn("name");
    when(overriddenVar.getValue()).thenReturn(Optional.of("Default"));

    when(templateGateway.list(any())).thenReturn(List.of(template));
    when(versionGateway.list(any())).thenReturn(List.of(version));
    when(variableGateway.list(any())).thenReturn(List.of(dbVar, overriddenVar));
    when(snippetGateway.list(any())).thenReturn(List.of());
    RenderedTemplate rendered = mock(RenderedTemplate.class);
    when(renderGateway.render(any())).thenReturn(rendered);

    // Call-site overrides "name" → "Alice"
    Optional<RenderedTemplate> result =
        usecase.render(input("CODE", tenant, Map.of("name", "Alice")));

    assertTrue(result.isPresent());
    verify(renderGateway).render(argThat(req -> {
      Map<String, String> vars = req.getVariables();
      return "Hi".equals(vars.get("greeting")) && "Alice".equals(vars.get("name"));
    }));
  }

