  @Test
  @DisplayName("render includes theme CSS asset when template has a theme with custom CSS")
  void render_includesThemeCssAsset() {
    Template template = globalTemplate("CODE");
    ThemeRef themeRef = mock(ThemeRef.class);
    when(template.getTheme()).thenReturn(Optional.of(themeRef));
    Theme theme = mock(Theme.class);
    when(theme.getCustomCss()).thenReturn(Optional.of("body { color: red; }"));
    when(themeGateway.resolve(themeRef)).thenReturn(theme);

    TemplateVersion version = version("<p>Hi</p>");
    when(templateGateway.list(any())).thenReturn(List.of(template));
    when(versionGateway.list(any())).thenReturn(List.of(version));
    RenderedTemplate rendered = mock(RenderedTemplate.class);
    when(renderGateway.render(any())).thenReturn(rendered);

    usecase.render(input("CODE", null, Map.of()));

    verify(renderGateway).render(argThat(req -> {
      List<RenderedAsset> assets = req.getAssets();
      return assets.size() == 1 && "theme-css".equals(assets.get(0).getCode())
          && "body { color: red; }".equals(assets.get(0).getContent());
    }));
  }

