  /**
   * Builds a {@link TemplateRenderInput} with the given code, optional tenant, and variables.
   */
  private TemplateRenderInput input(String code, TenantRef tenant, Map<String, String> vars) {
    return TemplateRenderInput.builder().code(code).channel(TemplateChannelOptions.MAIL)
        .tenant(tenant).variables(vars).build();
  }

  /**
   * Creates an enabled global (no tenant) {@link Template} mock matching channel EMAIL.
   */
  private Template globalTemplate(String code) {
    Template t = mock(Template.class);
    when(t.isEnabled()).thenReturn(true);
    when(t.getChannel()).thenReturn(TemplateChannelOptions.MAIL);
    when(t.getTenant()).thenReturn(Optional.empty());
    when(t.getTheme()).thenReturn(Optional.empty());
    return t;
  }

  /**
   * Creates an enabled tenant-specific {@link Template} mock matching channel EMAIL.
   */
  private Template tenantTemplate(String code, TenantRef tenant) {
    Template t = mock(Template.class);
    when(t.isEnabled()).thenReturn(true);
    when(t.getChannel()).thenReturn(TemplateChannelOptions.MAIL);
    when(t.getTenant()).thenReturn(Optional.of(tenant));
    when(t.getTheme()).thenReturn(Optional.empty());
    return t;
  }

  /**
   * Creates a {@link TemplateVersion} mock with the given HTML content and version number 1.
   */
  private TemplateVersion version(String html) {
    TemplateVersion v = mock(TemplateVersion.class);
    when(v.getContentHtml()).thenReturn(html);
    when(v.getSubject()).thenReturn(Optional.empty());
    when(v.getContentText()).thenReturn(Optional.empty());
    when(v.getVersion()).thenReturn(Optional.of(1));
    return v;
  }
